# Independent typed grammar: atom formats use little endian; v counts u32,
# layers counts i32, n6 is the counted six-short fixed native array.
SCHEMA = {
 'id': (0, ['h','h','I']),
 'hash': (0, ['I','i']),
 'handle': (1, ['i','I']),
 'reservation': (1, ['I','i','I']),
 'connection': (1, ['id','B','i']),
 'trade': (3, ['id','i','i','v:connection','v:id']),
 'efficiency': (4, ['I','i']+['B']*7+['i']*7+['v:i','i','I','i']),
 'plot': (1, ['i','i','i','B','id','I','I','i','i','n6']+['B']*12),
 'layer': (0, ['v:hash']*3),
 'build': (17, ['id','I','i','I']+['v:hash']*3+['I','i','B','i','i',
     'v:reservation','v:I','handle','v:handle','B','i','i','i','i',
     'v:i','v:i','v:i','v:efficiency','trade','v:i','v:plot','layers',
     'v:hash','v:hash','v:hash','i','i','v:hash']),
}


def current_record(raw):
    pos, items = 0, 0
    out = bytearray()
    cuts = set()
    noncanonical = Counter()
    noncanonical_occurrences = []
    context = []
    efficiencies = []
    nested = Counter()
    builds = []
    def atom(fmt):
        nonlocal pos
        size = struct.calcsize('<'+fmt)
        value = struct.unpack_from('<'+fmt, raw, pos)[0]
        out.extend(struct.pack('<'+fmt,value))
        pos += size
        return value
    def version(expected):
        actual=atom('I')
        if actual!=expected: raise ValueError(f'version {actual}, expected {expected}, at {pos-4}')
    def seq(t,n):
        nonlocal items
        if n < 0 or n > len(raw)-pos: raise ValueError('hostile count')
        items += n
        cuts.update((pos-4,pos))
        for _ in range(n): walk(t)
        cuts.add(pos)
    def walk(t):
        if len(t)==1:
            value=atom(t)
            if t=='B' and value not in (0,1):
                noncanonical[value]+=1
                noncanonical_occurrences.append(dict(offset=pos-1,value=value,field_path=list(context)))
            return value
        if t.startswith('v:'): seq(t[2:],atom('I')); return
        if t=='layers': seq('layer',atom('i')); return
        if t=='n6':
            n=atom('I')
            if n!=6: raise ValueError('unsupported neighbor count')
            seq('h',n); return
        v,fields=SCHEMA[t]
        if v: version(v)
        nested[t]+=1
        begin=pos-(4 if v else 0)
        for index,f in enumerate(fields):
            context.append(f"{t}[{index}]");walk(f);context.pop()
        if t=='efficiency': efficiencies.append(dict(start=begin,end=pos))
        if t=='build': builds.append(dict(start=begin,end=pos))
    version(2)
    player=atom('i')
    version(0x10001)
    if atom('I')!=16: raise ValueError('recycled block size mismatch')
    capacity=atom('I'); count=atom('I'); items+=count
    for _ in range(count):
        cuts.add(pos); atom('i'); walk('build'); cuts.add(pos)
    current_id_bits=atom('I'); n=atom('I'); first_free=atom('I'); last_free=atom('I')
    items+=n
    for _ in range(n): atom('I')
    cuts.update([0,1,2,3,4,7,8,12,16,20,24,pos-1])
    # Representative in-field cuts on the actual carrier in addition to every
    # nested sequence count/data/end and CityBuild record boundary.
    cuts.update(range(0,pos,max(1,pos//32)))
    if bytes(out)!=raw[:pos]: raise ValueError('typed reconstruction mismatch')
    return dict(player=player, consumed=pos, items=items, cuts=sorted(c for c in cuts if 0<=c<pos),
        live_city_builds=count, capacity=capacity, current_id_bits=current_id_bits,
        first_free=first_free,last_free=last_free,free_indices=n,
        nested=dict(nested),noncanonical_bool_bytes=dict(noncanonical),noncanonical_bool_occurrences=noncanonical_occurrences,builds=builds,efficiencies=efficiencies)


HARNESS = r'''use c6_core::{unit, player_ai_city_manager::{CityManager as Manager, Error}};
fn main() {
 let input=std::fs::read(std::env::args().nth(1).unwrap()).unwrap();
 let mut pos=0; let mut records=0; let mut tested_cuts=0;
 while pos<input.len() {
  let mut word=||{let n=u32::from_le_bytes(input[pos..pos+4].try_into().unwrap()) as usize;pos+=4;n};
  let size=word();let items=word();let num_cuts=word();
  let cuts=(0..num_cuts).map(|_|word()).collect::<Vec<_>>();
  let raw=&input[pos..pos+size];pos+=size;
  let lim=unit::Limits{max_bytes:size,max_items:items};
  let value=Manager::decode(raw,lim).unwrap();
  assert_eq!(value.encode_with_items(lim).unwrap(),(raw.to_vec(),items));
  assert_eq!(Manager::decode_prefix(raw,lim).unwrap(),(value.clone(),size));
  for end in cuts {assert!(Manager::decode(&raw[..end],lim).is_err(),"record {records} cut {end}");tested_cuts+=1;}
  for short in [unit::Limits{max_bytes:size-1,..lim},unit::Limits{max_items:items.saturating_sub(1),..lim}] {
   if short.max_items==items && short.max_bytes==size {continue;}
   assert_eq!(Manager::decode(raw,short),Err(Error::ResourceLimit));assert_eq!(value.encode(short),Err(Error::ResourceLimit));
  }
  let mut suffix=raw.to_vec();suffix.extend_from_slice(&[77;99]);
  assert_eq!(Manager::decode(&suffix,lim),Err(Error::Trailing));
  assert_eq!(Manager::decode_prefix_with_items(&suffix,lim).unwrap(),(value,size,items));
  records+=1;
 }
 println!("{records} {tested_cuts}");
}'''


def candidate(pin, payload, record_count, cut_count):
    pin=subprocess.check_output(['git','rev-parse',pin+'^{commit}'],cwd=ROOT,text=True).strip()
    archive=subprocess.check_output(['git','archive',pin],cwd=ROOT)
    with tempfile.TemporaryDirectory(prefix='c6-city-manager-') as directory:
        tmp=Path(directory);source=tmp/'source';source.mkdir()
        subprocess.run(['tar','-x','-C',str(source)],input=archive,check=True)
        # Every archived source is pinned before the build and remains unchanged.
        source_files={str(p.relative_to(source)):sha(p.read_bytes()) for p in source.rglob('*') if p.is_file()}
        driver=source/'tools/linux/player_ai_city_manager_audit.py'
        if driver.read_bytes()!=Path(__file__).read_bytes(): raise ValueError('audit driver differs from committed snapshot')
        module=source/'crates/c6-core/src/player_ai_city_manager.rs'
        if module.read_bytes()!=(ROOT/'crates/c6-core/src/player_ai_city_manager.rs').read_bytes(): raise ValueError('module differs from source commit')
        subprocess.run(['cargo','test','--offline','-p','c6-core','player_ai_city_manager::tests'],cwd=source,check=True)
        subprocess.run(['cargo','clippy','--offline','-p','c6-core','--all-targets','--','-D','warnings'],cwd=source,check=True)
        subprocess.run(['cargo','build','--offline','--release','-p','c6-core'],cwd=source,check=True)
        (tmp/'candidate.rs').write_text(HARNESS)
        command=['rustc','--edition=2021','-Dwarnings','-O',str(tmp/'candidate.rs'),'--extern','c6_core='+str(source/'target/release/libc6_core.rlib'),'-L','dependency='+str(source/'target/release/deps'),'-o',str(tmp/'candidate')]
        subprocess.run(command,check=True)
        (tmp/'records').write_bytes(payload)
        result=subprocess.check_output([str(tmp/'candidate'),str(tmp/'records')],text=True).strip()
        if result!=f'{record_count} {cut_count}': raise ValueError('candidate count mismatch')
        for path,digest in source_files.items():
            if sha((source/path).read_bytes())!=digest: raise ValueError('build mutated source '+path)
        return dict(source_commit=pin,archive_sha256=sha(archive),module_sha256=sha(module.read_bytes()),
            driver_sha256=sha(driver.read_bytes()),harness_sha256=sha(HARNESS.encode()),candidate_sha256=sha((tmp/'candidate').read_bytes()),
            all_archived_sources_verified_unchanged=True,source_files=len(source_files),
            native_records=record_count,actual_truncation_cuts=cut_count,exhaustive_actual_byte_prefixes=False,
            source_tests=3,exhaustive_small_source_prefixes=True,exact_and_one_short_shared_byte_item_caps=True,
            strict_trailing_refused=True,prefix_consumption_exact=True,cargo_module_tests=True,strict_clippy=True)


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--assets',type=Path,default=ROOT.parent/'c6-assets-linux')
    p.add_argument('--private-root',type=Path,default=ROOT.parent/'c6-ghidra')
    p.add_argument('--source-commit',help='Exact committed and exported c6-core candidate snapshot')
    p.add_argument('--output',type=Path,required=True)
    args=p.parse_args()
    binary=args.assets/'libGameCore_XP2.so';elf=Elf(binary,GAME_SHA);relocs=relocation_symbols(elf)
    methods=[]
    for address,size,name,digest in METHODS:
        if sha(elf.read(address,size))!=digest: raise ValueError('method mismatch '+name)
        asm=subprocess.check_output(['objdump','-d','-C',f'--start-address={address}',f'--stop-address={address+size}',str(binary)],text=True)
        edges=[];indirect=[]
        for line in asm.splitlines():
            m=re.search(r'^\s*([0-9a-f]+):.*?\b(call|jmp)\s+([0-9a-f]+) <(.*)>$',line)
            if m:
                target=int(m[3],16)
                if address<=target<address+size: continue
                stub=elf.read(target,6);body=target
                if stub[:2]==b'\xff\x25': body=relocs.get(target+6+struct.unpack_from('<i',stub,2)[0])
                edges.append(dict(site='0x'+m[1],target=hex(target),body=hex(body) if body is not None else None,name=m[4]))
            elif re.search(r'\b(call|jmp)\s+\*',line): indirect.append(line.split(':')[0].strip())
        methods.append(dict(address=hex(address),size=size,name=name,sha256=digest,direct_edges=edges,indirect_sites=indirect))
    for slot,body,name in VIRTUALS:
        if elf.relocated_pointer(slot)!=body: raise ValueError('virtual binding mismatch '+name)
    if struct.unpack('<II',elf.read(0x2dfbc20,8))!=(2,0x10001): raise ValueError('version constants mismatch')
    dwarf=subprocess.check_output(['gdb','-nx','-batch',str(binary)]+sum((['-ex',f"ptype /o '{n}'"] for n in ['GameCore::AI::CityManager','GameCore::AI::CityBuild','GameCore::AI::CityPlotInfo','GameCore::AI::CityPlotEvaluation','GameCore::AI::UnitEfficiencyInfo','GameCore::AI::Trade::City','GameCore::AI::Trade::CityTradeConnection']),[]),text=True)
    for field in ['m_cityAis','m_currentGpps','m_cachedUnitEvaluations','Neighbors','ExcludeFromEfficiencyCalculation','RailConnection']:
        if field not in dwarf: raise ValueError('missing DWARF '+field)
    fixtures=[];payload=bytearray();record_count=0;cut_count=0
    for identity,trace_name,trace_sha in FIXTURES:
        data=gzip.decompress((args.private_root/'evidence/linux-game-load/canonical'/(identity+'.bin.gz')).read_bytes())
        trace=gzip.decompress((args.private_root/'evidence/linux-save-normalization/checkpoint-203-owners'/trace_name).read_bytes())
        if sha(data)!=identity or sha(trace)!=trace_sha: raise ValueError('fixture identity mismatch')
        owners={x['call']:x for x in map(json.loads,trace.splitlines()) if x.get('event')=='owner' and x.get('save')==1}
        hooks=[x for x in owners.values() if x['owner'] in ['GameCore::AI::CityManager','GameCore::AI::CityBuild']]
        records=[]
        for row in sorted(owners.values(),key=lambda x:x['start']):
            if row['owner']!='GameCore::AI::Planning::Manager':continue
            parent=owners[row['parent']]
            if parent['owner']!='GameCore::Player::Instance':raise ValueError('parent mismatch')
            pv,player=struct.unpack_from('<Ii',data,parent['start'])
            if pv!=47:raise ValueError('Player version mismatch')
            start=row['end'];info=current_record(data[start:parent['end']]);end=start+info['consumed']
            if info['player']!=player or struct.unpack_from('<I',data,end)[0]!=15:raise ValueError('identity or next CultureAi version mismatch')
            native_efficiencies=sorted((x['start']-start,x['end']-start) for x in owners.values() if x['owner']=='GameCore::AI::UnitEfficiencyInfo' and start<=x['start']<end)
            projected_efficiencies=sorted((x['start'],x['end']) for x in info.pop('efficiencies'))
            if native_efficiencies!=projected_efficiencies:raise ValueError('nested original efficiency owner extent mismatch')
            info['nested_efficiency_owner_extents_matched']=len(native_efficiencies)
            raw=data[start:end];payload.extend(struct.pack('<III',len(raw),info['items'],len(info['cuts'])))
            payload.extend(struct.pack('<'+'I'*len(info['cuts']),*info['cuts']));payload.extend(raw)
            record_count+=1;cut_count+=len(info['cuts'])
            info.update(start=start,end=end,sha256=sha(raw),parent_call=parent['call'],planning_call=row['call'])
            info['actual_truncation_cut_count']=len(info.pop('cuts'))
            # Counts/identities are public evidence; raw proprietary bytes remain private.
            records.append(info)
        if len(records)!=43:raise ValueError('actual record count mismatch')
        fixtures.append(dict(core_sha256=identity,trace_sha256=trace_sha,actual_city_manager_hook_count=len(hooks),
            hook_absence_is_not_serialization_absence=True,records=records))
    report=dict(schema='c6-linux-player-ai-city-manager-v1',checks_passed=True,gamecore_sha256=GAME_SHA,
        audit_source_sha256=sha(Path(__file__).read_bytes()),methods=methods,virtual_bindings=VIRTUALS,
        dwarf_sha256=sha(dwarf.encode()),grammar=SCHEMA,fixtures=fixtures,
        current_versions=dict(city_manager=2,city_build=17,recycled=65537,trade_city=3,trade_connection=1,unit_efficiency=4,plot_evaluation=1,reservation=1,control_handle=1),
        original_execution=False,native_read_side_effects_reproduced=False,planning_only_exclusions=[],
        transitive_rng_audit_complete=False,unknown_bytes_masked=0,recorded_raw_save_load_difference_bytes=89198,
        next_dependency='CultureAi version 15',full_player=False,gameplay_state=False,actions=False,turns=False,
        reference_revision='5af389445118bed2bdebf7a8a42b219c8fba5175',reference_role='discovery only')
    if args.source_commit:report['candidate']=candidate(args.source_commit,payload,record_count,cut_count)
    args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps(dict(records=record_count,cuts=cut_count,checks_passed=True)))

if __name__=='__main__':main()
